INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter32-telangana-movement-after-1970', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p1", "partName": "Telangana Praja Samithi''s Early 1970 Activities", "bodyMd": "The Telangana Praja Samithi (T.P.S) began 1970 with a series of state-level mobilisation efforts aimed at pressing the Centre on the separate statehood demand.\n\n**First State-level meeting**\n- On **10th January, 1970**, the T.P.S State-level meeting was inaugurated by **Marri Chenna Reddy** at the Boys Scout Headquarters, Secunderabad.\n- **Nagari Krishna** was President of the invitation committee for this meeting.\n- **M.P. \"Gray\"** of the British Labour Party attended as a special guest.\n- At this meeting, Marri Chenna Reddy requested the Centre to hold a referendum on separate Telangana statehood.\n\n**Day of Protest and Martyr''s Day**\n- **15th January, 1970** was observed as a \"Day of Protest,\" marking one year since the launch of the Separate Telangana Movement.\n- A large open meeting was held at the Keshav Memorial ground, chaired by **M. Sridhar Reddy**.\n- On **21st January, 1970**, the two rival T.P.S factions — led by **Mrs. Sadalakshmi** and **M. Sridhar Reddy** — merged into a single entity.\n- Martyr **Shankar** had died during police firing at Sadashivpet on 24th January, 1969.\n- Mrs. Sadalakshmi called for **24th January, 1970** to be observed as **\"Martyr''s Day\"** in his memory.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p2", "partName": "Telangana United Front", "bodyMd": "Alongside the T.P.S, a parallel political formation emerged from within the state legislature.\n\n**Formation**\n- In January 1970, Telangana-seeking legislators met in Hyderabad under **Nukala Ram Chandra Reddy**''s chairmanship and decided to quit the State Government.\n- On **7th February, 1970**, **V.B. Raju** resigned from the State Cabinet, formed the **\"Telangana United Front\"**, and became its President, announcing that 35 MLAs and 12 MLCs backed the group.\n\n**Leadership and Recognition**\n- V.B. Raju — Chairman of the Front.\n- Nukala Ramachandra Reddy — leader of the Front in the State Assembly.\n- K. Rama Chandra Reddy — leader of the Front in the Council.\n- **Palvai Goverdhan Reddy**, the first signatory to the Front''s list, later withdrew; the remaining list was submitted to Assembly Speaker **B.V. Subba Reddy**.\n- On **9th February, 1970**, Speaker Subba Reddy recognised the Telangana United Front as the official opposition party.\n- The Front comprised 28 rebel Congressmen and 3 Independents (total 31 members).\n- **Rama Chandra Reddy** became Leader of Opposition, replacing **Gouthu Lachchanna**.\n- Key leaders who joined: Nukala Ram Chandra Reddy, Achyutha Reddy, Konda Laxman Bapuji, K. Ram Chandra Reddy.\n\n**Activities**\n- On **24th March, 1970**, during the budget speech by Finance Minister **Vijay Bhasker Reddy**, Front members walked out of the Assembly, demanding separate budget estimates for Andhra and Telangana regions.\n- At a public meeting at Tilak Park, Nizamabad, on **6th January, 1971**, V.B. Raju criticised the state government for neglecting Telangana''s economic and social development.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p3", "partName": "Centre''s Administrative Measures for Telangana (1969–70)", "bodyMd": "Parallel to political mobilisation, the Centre acted to strengthen the constitutional Regional Council mechanism and address grievances of Telangana employees.\n\n**Extended Powers to Telangana Regional Council**\n- On **7th March, 1970**, the President issued an order extending the powers of the Telangana Regional Council by amending the Andhra Pradesh Regional Committee Order, 1958.\n- These extended powers were to come into force from **9th March, 1970**.\n- New powers granted included: separate department-wise income–expenditure reporting for Andhra and Telangana regions; university education, jobs, and industry brought under the Committee''s ambit; recruitment rules for Telangana locals brought under the Committee''s ambit; the State Government required to report on implementation of the Centre''s decision on merger of services; and a report to be submitted every six months on action taken on the Committee''s recommendations.\n\n**High-Level Supervisory Committee on Employees'' Issues**\n- This Committee was constituted following a resolution passed by the Telangana Regional Committee in **August 1969**.\n- The State Government formed a high-level committee chaired by **Justice Nasirullah Baig** to examine issues concerning Telangana employees.\n- Other members: **Iqbal Chand** (member, Revenue Board), **C.R. Krishna Swamy** (Special Secretary, Board of Revenue), and **Rao Saheb**.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p4", "partName": "V.B. Raju''s Sub-State Demand", "bodyMd": "- In the Rajya Sabha elections held on **28th March, 1970**, V.B. Raju was elected to the Rajya Sabha from the Telangana region by a margin of 31 votes in the third round of counting under the legislators'' quota.\n- On **13th May, 1970**, speaking in the Rajya Sabha, V.B. Raju requested the Centre to grant Telangana **\"Sub-State\" status**, similar to Meghalaya''s.\n- Congress member **Mrs. Yashoda Reddy** opposed this proposal.\n- Dr. Chenna Reddy, referring to V.B. Raju''s remarks, stated in Hyderabad that there was no change in the Telangana demand.\n- The **Students Action Committee** opposed V.B. Raju''s comments.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p5", "partName": "Agitation and Parliamentary Debate (April–May 1970)", "bodyMd": "**Praja Samithi Satyagraha and Related Arrests**\n- The Telangana Praja Samithi organised a four-day personal satyagraha programme for the achievement of Telangana statehood.\n- **Nukala Ramchandra Reddy** led the satyagraha on its first day, **27th April, 1970**.\n- On **28th April**, the government arrested Members of Parliament **R. Surender Reddy**, **Rameswara Rao**, and other volunteers involved in the satyagraha.\n- On **3rd May, 1970**, Hyderabad City Mayor **Lakshminarayana** was arrested for holding a satyagraha in front of All India Radio for a separate Telangana.\n\n**Loksabha Debate on Telangana**\n- On **18th May, 1970**, Jansangh MP **Chand Goyal** stated in the Lok Sabha that the Central and State governments were trying to keep Telangana permanently backward.\n- Responding, **Y.B. Chavan** said the government was trying its best to create a suitable environment on the Telangana issue.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p6", "partName": "K.V. Ranga Reddy''s Death and the Pochampadu Project", "bodyMd": "- **K.V. Ranga Reddy** (80) died at 10:30 pm on **24th July, 1970**.\n- His body was covered with the Telangana flag, and the funeral was held at Amberpet Cemetery under government mandate.\n- On the same day, **24th July, 1970**, Chief Minister **Kasu Brahmananda Reddy** inaugurated the Pochampadu Project by releasing its waters into the south canal.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p7", "partName": "Telangana Praja Parishad and Allied Bodies", "bodyMd": "- The **\"Telangana Praja Parishad\"** was formed to pursue separate Telangana, with **K.R. Amos**, **Jagan Mohan Reddy**, **G.P. Saxena**, and **Ansari** among its important members.\n- On **3rd September, 1970**, about 250 MPs presented a memorandum to the Prime Minister proposing a legislative mechanism to implement the Telangana Regional Committee''s decisions.\n- On **3rd January, 1971**, the **\"Telangana Student Council\"** was started in Kachiguda, with **G. Sudarshan Reddy** of Osmania University Arts College as convener.\n- On **28th January, 1971**, T.P.S President Marri Chenna Reddy launched a weekly magazine, **\"Telangana Sentinel.\"**", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p8", "partName": "Evolution of Telangana Praja Samithi as a Political Party", "bodyMd": "- On **28th February, 1969**, students and lawyers formed the **\"Telangana People''s Convention,\"** which became the **\"Telangana Praja Samithi\"** on **25th March, 1969**, later transforming into a political party as political leaders joined it.\n- On **22nd–23rd July, 1970**, a State Council meeting at the T.P.S office in Hyderguda formally decided to convert the T.P.S into a political party, with a target of 10 lakh members; this proposal, approved by the working group on 22nd July, was ratified by the State Council on 23rd July.\n- **Konda Laxman Bapuji** opposed this decision.\n- On **4th January, 1971**, Marri Chenna Reddy formally announced the T.P.S as a political party.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p9", "partName": "Elections during the Movement (1970–71)", "bodyMd": "**Khairatabad By-election**\n- The by-election followed the death of Congress MLA **B.V. Guru Murthy**.\n- T.P.S nominated **Nagam Krishna Rao**, though **Konda Laxman** and **Sadalakshmi** opposed this and backed **Venkatesham** instead (who later withdrew).\n- Congress fielded **S. Yadagiri**.\n- On **15th June, 1970**, Nagam Krishna Rao won by a margin of about 14,000 votes; Chenna Reddy called it \"a victory of Telangana people.\"\n- Gram Panchayat elections were also held in 1970, in which the Praja Samithi won most Sarpanch posts, but its performance in indirect elections for Panchayat Samithi Presidents and Zilla Parishad Chairmen was nominal, attributed to the ruling party''s superior resources.\n\n**Legislative Council Elections**\n- On **24th June, 1970**, elections were held for six Legislative Council seats in Telangana; T.P.S contested 5 and won 3.\n- **Venkat Rami Reddy** (T.P.S, sitting MLC) won from one Hyderabad local constituency; Congress candidate **K. Prabhakar Reddy** won from another.\n- **P. Narsireddy** (Mahbubnagar) and **Souri Lakshma Reddy** (Medak) also won for T.P.S.\n- Seeing T.P.S''s growing strength, the government postponed the twin-cities'' municipal corporation elections, fearing defeat.\n\n**Siddipet By-election**\n- The Siddipet MLA seat fell vacant after V.B. Raju''s election to the Rajya Sabha.\n- On **17th November, 1970**, T.P.S candidate **Madan Mohan** defeated Congress''s **P.V. Rajeshwar Rao** by a margin of 19,800 votes.\n- Marri Chenna Reddy said the victory would ensure support for separate Telangana across all regions and communities.\n- Following this win, several parties reconsidered their stance: the **Jan Sangh** delegation at a Kakinada meeting said it would review its earlier opinion, and the **C.P.I** opined that a solution should be found for Telangana.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p10", "partName": "Split in the Praja Samithi and Negotiations with the Centre", "bodyMd": "- On **10th January, 1971**, at a T.P.S meeting in Sarojini Devi Hall, Hyderabad, Chenna Reddy''s pro-Prime Minister stance was condemned, resulting in the formation of a **\"New Praja Samithi.\"**\n- Alarmed by the Siddipet result, **Indira Gandhi** invited Marri Chenna Reddy to Delhi, proposing that T.P.S support Congress instead of contesting the upcoming Lok Sabha elections, with a possible merger.\n- Chenna Reddy conditioned any merger on Telangana statehood being formed.\n- Indira Gandhi proposed implementing an \"8-point formula,\" with Telangana to be formed after 5 years if two-thirds of Telangana legislators still found injustices persisting.\n- Chenna Reddy appointed a 14-member committee, convened by **Nukala Ramachandra Reddy**, to examine the proposal; the committee recommended a 2-year period instead of 5, tied to two-thirds support from legislators elected in the 1972 assembly elections — a condition Indira Gandhi did not accept.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p11", "partName": "Lok Sabha Elections, 1971", "bodyMd": "- In March 1971, Indira Gandhi dissolved the Lok Sabha and called general elections.\n- T.P.S, under Chenna Reddy, contested alone using the **\"Shovel\" (Salkepara)** symbol, with the slogan of eliminating economic disparities and achieving separate Telangana.\n- The Indira Congress contested with the **\"Cow-Calf\"** symbol.\n- T.P.S won **10 of 14** Lok Sabha seats in Telangana, securing **47.5%** of the vote — a sweep that gave the party its strongest bargaining position yet with the Centre.\n- Of the remaining 4 seats: Congress won 3 (Khammam, Nizamabad, Adilabad), and CPI(M)''s **Bhim Reddy Narsimha Reddy** won Miryalaguda.\n- The 10 T.P.S winners, spread across the region, were: **S.B. Giri** (Warangal), **Mallikarjun** (Medak), **G.S. Melkote** (Hyderabad), **G. Venkat Swamy** (Siddipet), **J. Rameshwar Rao** (Mahbubnagar), **M. Bhishma Dev** (Nagarkurnool), **M.M. Hashim** (Secunderabad), **V. Tulasi Ram** (Peddapalli), **K. Rama Krishna Reddy** (Nalgonda), and **M. Satyanarayana Rao** (Karimnagar).\n- Chenna Reddy himself did not contest, being under a six-year ban imposed by the Supreme Court.\n- Despite T.P.S''s regional sweep, Indira Gandhi, having won an absolute majority nationally, did not support separate Telangana statehood — but with the 1972 assembly elections approaching, she began efforts to merge the T.P.S into Congress.", "free": false}, {"partNumber": 12, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p12", "partName": "Merger of T.P.S with Congress", "bodyMd": "- Marri Chenna Reddy reached an oral agreement with Indira Gandhi on **6 conditions** regarding protections for Telangana, and merged the T.P.S with Congress, holding secret talks in Delhi while setting aside the movement''s original aspirations.\n- On **18th September, 1971**, the T.P.S State Council resolved to merge with Congress, after the Centre approved the Six Principles proposed by T.P.S.\n- On **19th September, 1971**, student leaders and Telangana activists convened a meeting condemning the Praja Samithi''s decision as a \"sabotage\" and resolved to continue the movement; **Mrs. Eshwari Bai, Purushottama Reddy, Sridhar Reddy, Pratap Kishore,** and **Santapuri Raghuveera Rao**, among others, formed the **\"Sampurna Telangana Praja Samithi\"** to carry it forward.\n\n**Six Principles proposed by T.P.S:**\n1. Removal of Brahmananda Reddy as Chief Minister (change of state leadership).\n2. Statutory powers for the Telangana Regional Committee.\n3. Formation of a Special Pradesh Congress Committee for Telangana.\n4. Separate budget and estimates for Telang' WHERE chapter_slug = 'telangana-history-en-chapter32-telangana-movement-after-1970';
UPDATE theory_content SET concepts_json = concepts_json || 'ana.\n5. Implementation of Mulky rules.\n6. An opportunity for Telangana legislators to decide on separate statehood, based on the government''s performance, if required.\n\n- Of these six proposals, only the **first** was implemented.\n\n**Leadership change and merger completion**\n- On **15th September, 1971**, Chief Minister **Brahmananda Reddy** resigned.\n- On **18th September, 1971**, the T.P.S working group decided to merge with Congress.\n- On **24th September, 1971**, the **All India Congress Committee (AICC)** accepted the merger proposal.\n- On **25th September, 1971**, AICC observer **C. Subramanyam** presided over the Congress legislative session to elect a new leader; **P.V. Narsimha Rao** was elected.\n- On **30th September, 1971**, P.V. Narsimha Rao became Chief Minister of Andhra Pradesh — the **first person from the Telangana region** to hold this office.", "free": false}, {"partNumber": 13, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p13", "partName": "P.V. Narasimha Rao", "bodyMd": "**Early Life**\n- Born **Pamulaparthi Venkat Narsimha Rao** on **28th June, 1921**, in Laknepally village, Warangal district.\n- Adopted by **Pamulaparthy Ranga Rao** and **Rukminamma** of Vangara village, Bheemadevarapalli mandal, Karimnagar district.\n- In 1938, he took part in the Vandemataram movement at Osmania University and was expelled.\n- He then joined Nagpur University, completed his LLB, and worked as a junior lawyer under **Burgula Ramakrishna Rao**.\n- He was a disciple of **Swami Ramananda Theertha** and was actively involved in State Congress politics.\n- He served as the founding President of the **Telugu Academy**, established in 1968.\n\n**Political Career in Andhra Pradesh**\n- First elected to the Andhra Pradesh Legislative Assembly in **1957** from **Manthani** constituency, on a Congress ticket; he represented Manthani for four consecutive terms (1957–1977).\n- Held ministerial portfolios: Justice and Information (1962–64), Justice and Endowments (1964–67), Health and Medical (1967), and later Education.\n- Served as Andhra Pradesh Chief Minister from **30th September, 1971** to **10th January, 1973**.\n\n**National Career**\n- First elected to the Lok Sabha in 1977 from **Hanumakonda**.\n- In the Union Government, he held the portfolios of Home Affairs, Defence, Planning Commission, and Foreign Affairs.\n- Became **Prime Minister of India** on **21st June, 1991**, serving until **16th May, 1996**, managing a minority government for five years — earning the title **\"Apara Chanukyudu.\"**\n- The **first South Indian** and the **only Telugu person** to become Prime Minister of India.\n- He assumed the Prime Ministership without being a sitting MP, later winning a by-election to the Lok Sabha from **Nandyal**.\n- Appointed economist **Man Mohan Singh** as Finance Minister and introduced India''s new liberalised economic policies.\n- Died on **23rd December, 2004**.\n\n**Literary Work**\n- Wrote an autobiography titled **\"Insider,\"** translated into Telugu as **\"Lopali Manishi\"** (Inner Person).\n- Could speak **17 languages**, including English, Hindi, and other southern languages.\n- Translated **Viswanatha Satyanarayana**''s Telugu classic **\"Veyipadagalu\"** into Hindi as **\"Sahasraphan,\"** for which he received the **Kendra Sahitya Akademi Award**.\n- Translated the Marathi novel **\"Pan Lakshat Kon Gheto\"** (But Who Pays Attention?) into Telugu as **\"Abala Jeevitham.\"**\n- Authored the well-known story **\"Golla Ramavva,\"** set against the backdrop of the Telangana armed struggle.", "free": false}, {"partNumber": 14, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p14", "partName": "Presidents of Telangana Praja Samithi", "bodyMd": "Leadership of the T.P.S changed hands rapidly in its first months — a sign of the internal factional tussle between Chenna Reddy, Sadalakshmi, and Madan Mohan before Chenna Reddy''s tenure stabilised from August 1969:\n\n1. **Ananthula Madan Mohan** — 25 March to 6 April 1969\n2. **B.S. Giri** (temporary) — 6 to 9 April 1969\n3. **T.N. Sada Lakshmi** — 9 to 25 April 1969\n4. **Ananthula Madan Mohan** (second term) — 25 April to 22 May 1969\n5. **Marri Chenna Reddy** (first term) — 22 May to 25 June 1969\n6. **Madan Mohan** (second term) — 25 June to 2 July 1969\n7. **T.N. Sada Lakshmi** (second term) — 3 July to 29 August 1969\n8. **Marri Chenna Reddy** (second, long-running term) — 29 August 1969 until the party''s merger with Congress on 24 September 1971", "free": false}, {"partNumber": 15, "conceptId": "telangana-history-en-chapter32-telangana-movement-after-1970-p15", "partName": "Organisations of the Early Movement Phase and Their Founders", "bodyMd": "The movement drew support from several distinct strands — literary/cultural bodies, student groups, professional unions, and pro-integration counter-groups formed by the opposing side. Grouping them by strand, rather than by date alone, shows how broad-based the mobilisation was.\n\n**Literary and cultural organisations**\n- **Navya Sahithya Samithi** (1952) — Kuruganti Sitaramaiah\n- **Sahitya Vikasa Mandali** (1960) — Vemuganti Narsimha Charyulu\n- **Medak District Writers'' Association** (1964) — Mudumbai Ranga Krishnama Charyulu\n- **Freeverse Front** (1966) — Kundurti Anjaneyulu\n- **Srujana**, a modern Telugu literary platform (1966) — Pendyala Varavara Rao\n- **Revolutionary Writers'' Association (Virasam)** (1971) — Varavara Rao\n- **Bharathiya Sahithya Samithi** (1971) — Ande Venkata Rajyam\n- **Jana Natya Mandali** (1972) — Gaddar\n\n**Student and youth organisations**\n- **Students Working Committee** (28 July 1952) — Buchaiah\n- **Telangana Students Working Committee** (13 January 1969) — Mallikarjun\n- **City Students Integrated Working Committee** (1969) — Gottem Gopal Reddy\n\n**Regional/political mobilisation bodies**\n- **Hyderabad Hitha Rakshana Samithi** (1952) — G. Rama Chary\n- **Mitra Mandali** (1957) — Udayaraju Seshagiri Rao and Pendyala Raghava Rao\n- **Telangana Maha Sabha** (1958)\n- **Telangana Regional Council** (1968) — Kolishetty Ramdasu\n- **Telangana Protection Committee** (13 January 1969) — Katam Lakshmi Narayana\n- **Telangana Praja Samithi (T.P.S)** (25 March 1969) — Madan Mohan\n- **Sampurna Telangana Praja Samithi** (1969) — Satyanarayana Reddy and Keshav Rao Jadhav\n- **Telangana Udyama Samanvaya Sangham** (1969) — Achyuth Reddy\n- **Telangana Praja Parishad** (1969) — K.R. Amos\n- **Telangana Vimochana Samithi** (1969) — K. Narsimha Reddy\n- **Special Telangana Congress Forum** (4 July 1971) — Marri Chenna Reddy\n\n**Professional and employee unions**\n- **Telangana University College Teachers'' Convention** (20 May 1969) — Prof. Shah Manjur Alam\n- **Telangana NGOs'' Union** (1969) — Amos\n- **Telangana Advocates Union** (1969) — B.C. Jain\n- **Telangana Integration Union** (1969) — G. Venkata Swamy\n- **Labourers Joint Action Committee** (1969) — Govinda Singh\n\n**Pro-integration counter-groups (opposing separate Telangana)**\n- **Poti Telangana Praja Samithi**, a rival/competing T.P.S (May 1969) — Sridhar Reddy\n- **Telangana Congress Samithi** (1969) — Konda Laxman Bapuji\n- **Public Integration Committee** (Powrula Samaikyatha Sangam) (3 April 1969) — G. Venkata Swamy\n- **Bhava Samaikyatha Praja Sanghatana** (1969) — Swamy Ramananda Theertha\n- **Rashtra Samaikyatha Samrakshana Samithi** (1969) — P.V. Ranga Rao\n- **Poti T.N.G.O**, a rival/competing T.N.G.O (1969) — Harinath Rao\n\nThis split between separatist and integrationist bodies, especially visible in 1969, reflects how contested and organisationally fragmented the Telangana question had already become well before the T.P.S–Congress merger of 1971.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter32-telangana-movement-after-1970';
